1	"use client";
2	
3	import { useCallback, useEffect, useRef, useState } from "react";
4	import { useRouter } from "next/navigation";
5	import { StylistView, type StylistStatus } from "./stylist-view";
6	import { generate, saveLocation } from "@/app/generate/actions";
7	import { searchCities, type City } from "@/lib/weather/geocode";
8	import { getCurrentPosition, permissionState, GeoError } from "@/lib/weather/geolocate";
9	import type { LocationSource } from "@/lib/weather/location";
10	import type { Look, UiOccasion, WeatherPayload } from "@/lib/generator/types";
11	
12	type Chosen = { lat: number; lon: number; label: string; source: LocationSource };
13	
14	const DENIED_COPY = "Location access is off — search for a city instead.";
15	const FAILED_COPY = "Couldn't get your location — search for a city instead.";
16	
17	export function Stylist() {
18	  const router = useRouter();
19	  const [status, setStatus] = useState<StylistStatus>("loading");
20	  const [occasion, setOccasion] = useState<UiOccasion>("everyday");
21	  const [formality, setFormality] = useState<number | null>(null);
22	  const [mustColors, setMustColors] = useState<string[]>([]);
23	  const [city, setCity] = useState<Chosen | null>(null);
24	  const [nonce, setNonce] = useState(0);
25	
26	  const [weather, setWeather] = useState<WeatherPayload | null>(null);
27	  const [looks, setLooks] = useState<Look[]>([]);
28	  const [selectedLook, setSelectedLook] = useState(0);
29	  const [cities, setCities] = useState<City[]>([]);
30	  const [refineOpen, setRefineOpen] = useState(false);
31	  const [missing, setMissing] = useState<string | null>(null);
32	  const [locating, setLocating] = useState(false);
33	  const [geoError, setGeoError] = useState<string | null>(null);
34	  // Optimistic: the row shows until we learn the browser has no geolocation at
35	  // all, at which point it disappears and city search is the only path.
36	  const [geoSupported, setGeoSupported] = useState(true);
37	
38	  // The silent refresh must never overwrite a location the user meant to keep.
39	  // Two ways that can happen, both guarded here:
40	  //   1. a RACE — the async permission→position chain resolving after the user
41	  //      has already picked a city in this session;
42	  //   2. a SAVED CITY — profiles.location_source === 'city' is a deliberate
43	  //      choice (decision L2), so GPS must not silently replace it.
44	  // The fix is parked in a ref until both gates are known, so geolocation still
45	  // starts immediately rather than waiting on the first generate to return.
46	  const userChoseRef = useRef(false);
47	  const pendingGeoRef = useRef<Chosen | null>(null);
48	  const geoAllowedRef = useRef<boolean | null>(null); // null = stored origin unknown yet
49	
50	  const applyPendingGeo = useCallback(() => {
51	    if (userChoseRef.current) return; // gate 1
52	    if (geoAllowedRef.current !== true) return; // gate 2
53	    const fix = pendingGeoRef.current;
54	    if (!fix) return;
55	    pendingGeoRef.current = null;
56	    setCity(fix);
57	  }, []);
58	
59	  useEffect(() => {
60	    let cancelled = false;
61	    permissionState().then((state) => {
62	      if (cancelled) return;
63	      if (state === "unsupported") {
64	        setGeoSupported(false);
65	        return;
66	      }
67	      if (state !== "granted") return; // querying never prompts; reading would
68	      getCurrentPosition()
69	        .then((c) => {
70	          if (cancelled) return;
71	          pendingGeoRef.current = { ...c, label: "Current location", source: "geo" };
72	          applyPendingGeo();
73	        })
74	        .catch(() => {
75	          /* silent path — never surface an error the user didn't ask for */
76	        });
77	    });
78	    return () => {
79	      cancelled = true;
80	    };
81	  }, [applyPendingGeo]);
82	
83	  // An explicit tap always wins, including over a saved city.
84	  const useMyLocation = useCallback(() => {
85	    userChoseRef.current = true;
86	    pendingGeoRef.current = null;
87	    setLocating(true);
88	    setGeoError(null);
89	    getCurrentPosition()
90	      .then((c) => setCity({ ...c, label: "Current location", source: "geo" }))
91	      .catch((e) =>
92	        setGeoError(e instanceof GeoError && e.kind === "denied" ? DENIED_COPY : FAILED_COPY),
93	      )
94	      .finally(() => setLocating(false));
95	  }, []);
96	
97	  useEffect(() => {
98	    let cancelled = false;
99	    setStatus("loading");
100	    generate({ occasion, formality, mustColors, city: city ?? undefined }).then((res) => {
101	      if (cancelled) return;
102	      // The first result tells us the STORED provenance. A saved city blocks the
103	      // silent refresh for good; anything else releases the parked GPS fix.
104	      if (geoAllowedRef.current === null && res.status !== "error") {
105	        geoAllowedRef.current = res.weather.locationOrigin !== "city";
106	        applyPendingGeo();
107	      }
108	
109	      if (res.status === "ok") {
110	        setWeather(res.weather);
111	        setLooks(res.looks);
112	        setSelectedLook(0);
113	        setStatus("ok");
114	      } else if (res.status === "empty") {
115	        setWeather(res.weather);
116	        setLooks([]);
117	        setMissing(res.missing);
118	        setStatus("empty");
119	      } else {
120	        setStatus("error");
121	      }
122	
123	      // Persist only a location the user actually supplied — including the
124	      // silent refresh, which is the point of keeping the record fresh. Never
125	      // for the profile/default fallback: there is nothing new to write.
126	      if (city && res.status !== "error") {
127	        saveLocation({ ...city, timezone: res.weather.timezone }).catch(() => {
128	          /* non-fatal — never disturb the looks */
129	        });
130	      }
131	    });
132	    return () => {
133	      cancelled = true;
134	    };
135	  }, [occasion, formality, mustColors, city, nonce]);
136	
137	  return (
138	    <StylistView
139	      status={status}
140	      weather={weather}
141	      looks={looks}
142	      selectedLook={selectedLook}
143	      occasion={occasion}
144	      cities={cities}
145	      refineOpen={refineOpen}
146	      missing={missing}
147	      locating={locating}
148	      geoError={geoError}
149	      onOccasion={setOccasion}
150	      onOpenRefine={() => setRefineOpen(true)}
151	      onCloseRefine={() => setRefineOpen(false)}
152	      onRefineApply={({ formality: f, mustColors: c }) => {
153	        setFormality(f);
154	        setMustColors(c);
155	        setRefineOpen(false);
156	      }}
157	      onCityChange={(c) => {
158	        userChoseRef.current = true;
159	        pendingGeoRef.current = null;
160	        setCity({ lat: c.lat, lon: c.lon, label: c.name, source: "city" });
161	      }}
162	      onCitySearch={(q) => {
163	        if (q.trim().length < 2) return;
164	        searchCities(q).then(setCities);
165	      }}
166	      onUseMyLocation={geoSupported ? useMyLocation : undefined}
167	      onSelectLook={setSelectedLook}
168	      onRetry={() => setNonce((n) => n + 1)}
169	      onOpenItem={(id) => router.push(`/closet/${id}`)}
170	    />
171	  );
172	}
173

